import{_ as r,I as i,c as s,o as t,a3 as a,b as l,w as n,a as d,J as c,a4 as p}from"./chunks/framework.Cc9k46oU.js";const v=JSON.parse('{"title":"Business Administrator Operational Governance Guide","description":"Practical guide to Human-in-the-Loop (HITL) approval workflows and FinOps token budget management for business operators, department heads, and security approvers","frontmatter":{"title":"Business Administrator Operational Governance Guide","shortTitle":"Operations Guide Overview","category":"Operations Guide","sort":1,"description":"Practical guide to Human-in-the-Loop (HITL) approval workflows and FinOps token budget management for business operators, department heads, and security approvers","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/guide/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/guide/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/guide/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/guide/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/guide/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Business Administrator Operational Governance Guide | Empasy Docs"}],["meta",{"property":"og:description","content":"Practical guide to Human-in-the-Loop (HITL) approval workflows and FinOps token budget management for business operators, department heads, and security approvers"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/guide/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Business Administrator Operational Governance Guide | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Practical guide to Human-in-the-Loop (HITL) approval workflows and FinOps token budget management for business operators, department heads, and security approvers"}]]},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1795293539000}'),g={name:"en/guide/index.md"};function u(m,e,h,y,f,b){const o=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="business-administrator-operational-governance-guide" tabindex="-1">Business Administrator Operational Governance Guide <a class="header-anchor" href="#business-administrator-operational-governance-guide" aria-label="Permalink to “Business Administrator Operational Governance Guide”">​</a></h1><h2 id="_1-overview-and-target-audience" tabindex="-1">1. Overview and Target Audience <a class="header-anchor" href="#_1-overview-and-target-audience" aria-label="Permalink to “1. Overview and Target Audience”">​</a></h2><p>SyncSeries provides a web-based management console and governance tooling so that not only software engineers, but also <strong>business department managers, product planners, and security reviewers</strong> can safely control and operate AI agents.</p><p>This guide is written for practitioners performing the following roles:</p><ul><li><strong>Department Heads &amp; Approvers</strong>: Making approve/reject decisions for high-risk tasks requested by agents (such as bulk data modifications and production deployments).</li><li><strong>FinOps &amp; Finance Officers</strong>: Tracking monthly AI model invocation costs by department/project and managing budget caps.</li><li><strong>Compliance &amp; Audit Officers</strong>: Conducting tamper-proof audits of historical agent actions, decision rationale, and prompt logs.</li></ul>',5)),(t(),l(p,null,{default:n(()=>[c(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Agent%5B%22Autonomous%20AI%20Agent%22%5D%20--%3E%20Danger%7B%22High-Risk%20Task%20Check%20(DB%20Change%2C%20Deployment%2C%20etc.)%22%7D%0A%20%20%20%20Danger%20--%20%22Standard%20Read%20Query%20(Safe)%22%20--%3E%20Auto%5B%22Auto-Execute%20%26%20WORM%20Audit%20Log%22%5D%0A%20%20%20%20Danger%20--%20%22High-Risk%20Task%20Detected%22%20--%3E%20HITL%5B%22Enqueue%20in%20HITL%20Multi-Stage%20Approval%20Queue%22%5D%0A%20%20%20%20%0A%20%20%20%20HITL%20--%3E%20Approver%5B%22Notify%20Department%20Head%20%2F%20Admin%20Console%22%5D%0A%20%20%20%20Approver%20--%3E%20Choice%7B%22Admin%20Review%20Outcome%22%7D%0A%20%20%20%20Choice%20--%20%22Approve%22%20--%3E%20Exec%5B%22Atomic%20Execution%20%26%20Result%20Report%22%5D%0A%20%20%20%20Choice%20--%20%22Reject%22%20--%3E%20Abort%5B%22Cancel%20Task%20%26%20Compensating%20Rollback%20Transaction%22%5D%0A%20%20%20%20Choice%20--%20%22Amend%22%20--%3E%20Agent%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-core-governance-principles" tabindex="-1">2. Core Governance Principles <a class="header-anchor" href="#_2-core-governance-principles" aria-label="Permalink to “2. Core Governance Principles”">​</a></h2><ol><li><strong>Principle of Least Privilege</strong>: <ul><li>Each agent and user can execute only the tools and UI permissions mapped to their assigned role (<code>sys_role</code>).</li></ul></li><li><strong>Multi-Party Human-in-the-Loop (HITL)</strong>: <ul><li>Destructive actions or payment/pricing modifications exceeding defined thresholds require sequential approval from two or more parties rather than a single administrator before final execution.</li></ul></li><li><strong>Tamper-Proof Audit Trail</strong>: <ul><li>All approval decisions and agent execution logs are sealed in a timestamped cryptographic hash chain, making post-hoc alteration or deletion impossible.</li></ul></li></ol><hr><h2 id="_3-daily-weekly-operational-checklist-by-role" tabindex="-1">3. Daily &amp; Weekly Operational Checklist by Role <a class="header-anchor" href="#_3-daily-weekly-operational-checklist-by-role" aria-label="Permalink to “3. Daily &amp; Weekly Operational Checklist by Role”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Role</th><th style="text-align:center;">Frequency</th><th style="text-align:left;">Key Inspection Items</th><th style="text-align:left;">Admin Console Menu &amp; Reference Manual</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Department Head / Approver</strong></td><td style="text-align:center;">Continuous</td><td style="text-align:left;">• Check the approval queue for Level 3-4 high-risk tasks (bulk price changes, schema modifications, deployments)<br>• Verify before/after data diffs and rollback snapshot ID generation</td><td style="text-align:left;"><code>SyncVerse &gt; Task Approvals (/governance)</code><br><a href="./hitl-approval-operations">HITL Approval Manual</a></td></tr><tr><td style="text-align:left;"><strong>FinOps / IT Planning Team</strong></td><td style="text-align:center;">Weekly</td><td style="text-align:left;">• Monitor monthly token budget consumption rates by department and agent (70% / 90% thresholds)<br>• Check semantic cache hit rate (<code>&gt;= 35%</code>) and lightweight model (Tier 1-2) auto-routing ratio</td><td style="text-align:left;"><code>SyncLLM &gt; FinOps Ledger</code><br><a href="./finops-budget-operations">FinOps Budget Manual</a></td></tr><tr><td style="text-align:left;"><strong>Information Security / Audit Team</strong></td><td style="text-align:center;">Monthly</td><td style="text-align:left;">• Audit PII (national ID numbers, bank accounts, card numbers, contact details) masking incidents in external LLM calls<br>• Verify SHA-256 hash chain audit log integrity and unauthorized API (<code>SyncAPIM</code>) block records</td><td style="text-align:left;"><code>SyncAPIM &gt; Threat Detection Logs</code><br><code>SyncWatch &gt; Security Pack Deployment Ledger</code></td></tr></tbody></table><hr><h2 id="_4-emergency-response-1-click-rollback-standard-operating-procedure-sop" tabindex="-1">4. Emergency Response &amp; 1-Click Rollback Standard Operating Procedure (SOP) <a class="header-anchor" href="#_4-emergency-response-1-click-rollback-standard-operating-procedure-sop" aria-label="Permalink to “4. Emergency Response &amp; 1-Click Rollback Standard Operating Procedure (SOP)”">​</a></h2><p>If unexpected metric anomalies or business complaints arise immediately after an autonomous agent task is applied, administrators can restore the previous state immediately without waiting for engineering code fixes by following this three-step procedure:</p><ol><li><strong>Step 1 — Identify Execution History and Snapshot</strong>: <ul><li>In <code>SyncVerse</code> or the relevant domain agent (<code>SyncShop</code>, <code>SyncCMS</code>, <code>SyncBoot</code>) under <strong>[Task Approvals &gt; Execution Audit History]</strong>, locate the most recently executed task ID and its auto-issued snapshot identifier (<code>SNP-YYYYMM-NNN</code>).</li></ul></li><li><strong>Step 2 — Trigger 1-Click Compensating Rollback</strong>: <ul><li>Click <strong>[Restore Immediately to Previous Snapshot (Rollback)]</strong> on the corresponding history card to execute the backend compensating transaction (<code>revert_data_state</code> or <code>ROLLBACK_PRICE</code>) and restore the pre-change data state within <code>1 second</code>.</li></ul></li><li><strong>Step 3 — Root Cause Analysis (RCA) and Guardrail Calibration</strong>: <ul><li>Review the <code>SyncInsight</code> RCA report to identify the root cause, and if necessary, elevate the tool&#39;s risk level or recalibrate constraint parameters (e.g., minimum guaranteed margin rate, maximum affected record count).</li></ul></li></ol><hr><h2 id="_5-detailed-operational-manuals" tabindex="-1">5. Detailed Operational Manuals <a class="header-anchor" href="#_5-detailed-operational-manuals" aria-label="Permalink to “5. Detailed Operational Manuals”">​</a></h2><ul><li><strong><a href="./hitl-approval-operations">4-Stage HITL Approval and Snapshot Rollback Manual</a></strong>: Receiving approval requests in the web console, reviewing detailed diffs and impact scope, executing approve/reject/amend actions, and performing snapshot rollbacks.</li><li><strong><a href="./finops-budget-operations">FinOps Budget Guardrails and Model Routing Manual</a></strong>: Allocating organization-level monthly budgets, threshold alert policies, automatic model tiering, and overspend prevention procedures.</li></ul>',13))])}const A=r(g,[["render",u]]);export{v as __pageData,A as default};
